Given an array of distinct integers arr[], a surpasser of an element arr[i] is any element arr[j] such that j > i and arr[j] > arr[i]. Find the number of surpassers for each element in the array.Examples: Input: arr[] = [2, 7, 5, 3, 8, 1]Output: [4, 1, 1, 1, 0, 0]Explanation:  For 2, there are 4 greater elements to its right: [7, 5, 3, 8]For 7, there is 1 greater element to its right: [8]For 5, there is 1 greater element to its right: [8]For 3, there is 1 greater element to its right: [8]For 8, there is no greater element to its right: [0]For 1, there is no greater element to its right: [0]Input: arr[] = [4, 5, 1]Output: [1, 0, 0]Explanation: For 4, there is 1 greater element to its right: [5]For 5, there is no greater element to its right: [0]For 1, there is no greater element to its right: [0]Try It YourselfTable of Content[Naive Approach] - Using Two Nested Loops - O(n^2) Time and O(1) Space[Expected Approach] - Using Merge Step of Merge Sort - O(n Log n) Time and O(n) Space[Naive Approach] - Using Two Nested Loops - O(n^2) Time and O(1) SpaceThe simplest approach is to iterate through the array, and for each element count the number of elements to its right that is greater than it.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> findSurpasser(vector<int> &arr) {
    int n = arr.size();

    // array to store surpasser counts
    vector<int> res(n, 0);

    for (int i = 0; i < n; i++) {

        // Find surpasser for arr[i]
        int count = 0;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] > arr[i])
                count++;
        }

        res[i] = count; 
    }
    return res;
}

int main() {
    vector<int> arr = {2, 7, 5, 3, 8, 1};
    vector<int> res = findSurpasser(arr);    
    for (int count : res) 
        cout << count << " ";

    return 0;
}


