Output4 1 1 1 0 0 [Expected Approach] - Using Merge Step of Merge Sort - O(n Log n) Time and O(n) SpaceIn this approach, we use the merge step of merge sort. During the merge, if the ith element in the left half is smaller than the jth element in the right half, it means that all remaining elements in the right half (from j to end) are greater than the ith element in the left half (since both halves are sorted). Therefore, we add the number of remaining elements in the right half to the surpasser count of the ith element of the left half. This process is repeated for all elements in the left half as they are merged with the right half.Since all the elements in the array are distinct, we use a hash map to keep store of the surpasser count for each element. After the merge sort is complete, we fill the result array with the surpasser counts, maintaining the same order as the original input.
            C++

    #include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

// Merge function to sort the array and update surpasser counts
int merge(vector<int> &arr, int lo, int mid, int hi, 
                            unordered_map<int, int> &m) {

    int n1 = mid - lo + 1;
    int n2 = hi - mid;
    vector<int> left(n1), right(n2); 

    // Copy data into temporary arrays left[] and right[]
    for (int i = 0; i < n1; i++)
        left[i] = arr[lo + i]; 

    for (int j = 0; j < n2; j++)
        right[j] = arr[mid + 1 + j]; 

    int i = 0, j = 0, k = lo;

    // Merging two halves
    while (i < n1 && j < n2) {

        // All elements in right[j..n2] are greater than left[i]
        // So add n2 - j, in surpasser count of left[i]
        if (left[i] < right[j]) {
            m[left[i]] += n2 - j;  
            arr[k++] = left[i++];
        } 
        else {
            arr[k++] = right[j++];
        }
    }

    // Copy remaining elements of left[] if any
    while (i < n1)
        arr[k++] = left[i++];

    // Copy remaining elements of right[] if any
    while (j < n2)
        arr[k++] = right[j++];
}

void mergeSort(vector<int> &arr, int lo, int hi, 
               unordered_map<int, int> &m) {
    if (lo < hi) {
        int mid = lo + (hi - lo) / 2;

        // Sort left and right half
        mergeSort(arr, lo, mid, m); 
        mergeSort(arr, mid + 1, hi, m);

        // Merge them
        merge(arr, lo, mid, hi, m);  
    }
}

vector<int> findSurpasser(vector<int>& arr) {
    int n = arr.size();

    // Map to store surpasser counts
    unordered_map<int, int> m;

    // Duplicate array to perform merge Sort
    // so that orginial array is not modified
    vector<int> dup = arr;  

    mergeSort(dup, 0, n - 1, m);  

    // Store surpasser counts in result array
    // in the same order as given array
    vector<int> res(n);
    for (int i = 0; i < n; i++)
        res[i] = m[arr[i]]; 

    return res;
}

int main() {
    vector<int> arr = {2, 7, 5, 3, 8, 1};
    vector<int> res = findSurpasser(arr);  
    for (int count : res)
        cout << count << " ";
    return 0;
}


