    using System;
using System.Collections.Generic;

class GfG {

    // Merge function to sort the array 
    // and update surpasser counts
    static void merge(int[] arr, int lo, int mid, int hi, 
                      Dictionary<int, int> m) {

        int n1 = mid - lo + 1;
        int n2 = hi - mid;

        int[] left = new int[n1];
        int[] right = new int[n2];

        // Copy data into temporary arrays
        for (int i = 0; i < n1; i++)
            left[i] = arr[lo + i];

        for (int j = 0; j < n2; j++)
            right[j] = arr[mid + 1 + j];

        int i1 = 0, j1 = 0, k = lo;

        // Merge the two halves
        while (i1 < n1 && j1 < n2) {

            // Count surpassers
            if (left[i1] < right[j1]) {
                if (!m.ContainsKey(left[i1]))
                    m[left[i1]] = 0;
                m[left[i1]] += n2 - j1;
                arr[k++] = left[i1++];
            }
            else {
                arr[k++] = right[j1++];
            }
        }

        // Copy remaining elements
        while (i1 < n1)
            arr[k++] = left[i1++];
        while (j1 < n2)
            arr[k++] = right[j1++];
    }

    static void mergeSort(int[] arr, int lo, int hi, 
                          Dictionary<int, int> m) {
        if (lo < hi) {
            int mid = lo + (hi - lo) / 2;

            // Recursive sort
            mergeSort(arr, lo, mid, m);
            mergeSort(arr, mid + 1, hi, m);

            // Merge sorted halves
            merge(arr, lo, mid, hi, m);
        }
    }

    static List<int> findSurpasser(int[] arr) {
        int n = arr.Length;
        Dictionary<int, int> m = new Dictionary<int, int>();

        int[] dup = new int[n];
        Array.Copy(arr, dup, n);

        mergeSort(dup, 0, n - 1, m);

        List<int> res = new List<int>();
        for (int i = 0; i < n; i++) {
            res.Add(m.ContainsKey(arr[i]) ? m[arr[i]] : 0);
        }

        return res;
    }

    static void Main() {
        int[] arr = {2, 7, 5, 3, 8, 1};
        List<int> res = findSurpasser(arr);
        foreach (int count in res)
            Console.Write(count + " ");
    }
}


